export const SANKHYA_TEMPLATE_COUNT = Object.keys(MODELS).length;

export function normalizeObligationTemplateKey(value) {
  return String(value || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()
    .replace(/\s+/g, ' ');
}

export function getSankhyaChecklistModel(obligationOrName) {
  const name = typeof obligationOrName === 'string' ? obligationOrName : obligationOrName?.name;
  return MODELS[normalizeObligationTemplateKey(name)] || null;
}

export function getSankhyaChecklistTemplate(obligationOrName) {
  return getSankhyaChecklistModel(obligationOrName)?.tasks?.slice() || [];
}

export function getSankhyaChecklistSuggestions(obligationOrName) {
  const model = getSankhyaChecklistModel(obligationOrName);
  if (!model) return [];
  return model.tasks.map((description, index) => ({
    description,
    score: 10 - (index * 0.001),
    origin: `Modelo Sankhya · ${model.profile || 'planilha'}`,
  }));
}
